def _operator(u, v, transform, limits, mask=None):
    from scipy.optimize import minimize_scalar
    if mask is not None:
        (u, v) = (u[mask], v[mask])

    def design(x, k):
        return np.column_stack((_affine(x), transform(x, k)))

    def objective(k):
        a = design(u, k)
        return np.sum((a @ _fit(a, v) - v) ** 2)
    grid = np.linspace(*limits, 41)
    i = int(np.argmin([objective(k) for k in grid]))
    k = minimize_scalar(objective, bounds=(grid[max(i - 1, 0)], grid[min(i + 1, 40)]), method='bounded', options={'xatol': 1e-09}).x
    w = _fit(design(u, k), v)
    return lambda x: design(x, k) @ w

def _calibration(panel):
    (u, v) = (panel['u'], panel['v'])
    a = _affine(u)
    mask = np.ones(len(u), dtype=bool)
    for _ in range(8):
        w = _ls(a[mask], v[mask])
        e = np.linalg.norm(a @ w - v, axis=1)
        new = e <= max(1e-10, 4 * np.median(e))
        if new.sum() < 8 or np.array_equal(mask, new):
            break
        mask = new
    d = np.array([_ls(a[mask][:, [0, j + 1]], v[mask, j]) for j in range(4)]).T
    if np.median(np.linalg.norm((u * d[1] + d[0] - v)[mask], axis=1)) <= 1.35 * np.median(e[mask]) + 1e-10:
        return (d[0], np.diag(d[1]))
    return (w[0], w[1:])

def _temporal_basis(times, trajectories):
    from scipy.optimize import least_squares
    t = np.asarray(times)

    def basis(rates):
        return -np.expm1(-t[:, None] * rates)

    def err(rates):
        f = basis(rates)
        return (f @ _ls(f, trajectories.T) - trajectories.T).ravel()
    opt = least_squares(err, [1.8, 0.43], bounds=([0.8, 0.03], [8.0, 0.79]), max_nfev=80)
    return np.linalg.qr(basis(opt.x), mode='reduced')[0]

def _operators(panel, q):
    u = panel['u']
    p = _operator(u, panel['v1'], lambda x, k: x / (1 + k * abs(x)), (0.2, 2.0))(q)
    r = _operator(u, panel['v2'], lambda x, k: x * x / (1 + k * x * x), (0.02, 0.6))(q)
    return (p, r)
